#!/usr/bin/env python3
"""Round 91b tiles (27 September): Global Safety Net's country rankings read from their spreadsheet (scripts/gsn_rankings.py);
the round 90b builds that duplicated Global Safety Net's layers taken out (human_modification, wilderness, reforestation and
anything they built). Needs round 90b tiles first. Upload to the culprits-tiles-more repo's patches folder. Safe to run twice."""
import base64, os, pathlib, sys
if not os.path.isdir("scripts"):
    sys.exit("Run this from the culprits-tiles-more folder.")
changed = 0
p = pathlib.Path("scripts/gsn_rankings.py")
data = base64.b64decode("""""")
if not (p.exists() and p.read_bytes() == data):
    p.write_bytes(data); changed += 1; print("written:", p)
gone = ["scripts/human_modification.py", "scripts/wilderness.py", "scripts/reforestation.py"]
gone += [str(x) for x in pathlib.Path("tiles").glob("own_modification*")]
gone += [str(x) for x in pathlib.Path("tiles").glob("own_wilderness*")]
gone += [str(x) for x in pathlib.Path("tiles").glob("own_reforestation*")]
for g_ in gone:
    if os.path.exists(g_):
        os.remove(g_); changed += 1; print("removed:", g_)
print(f"{changed} change(s)" if changed else "Already applied. Nothing changed.")
